const items = $input.all();
const normalizedJobs = [];

// PERSISTENT DEDUPLICATION ENGINE: Retains seen job identifiers across scheduled executions
const staticData = $getWorkflowStaticData('global');
staticData.seenJobKeys = staticData.seenJobKeys || [];

const techKeywords = [
  'software', 'developer', 'engineer', 'frontend', 'backend', 'fullstack',
  'web', 'mobile', 'android', 'ios', 'flutter', 'react', 'python',
  'javascript', 'typescript', 'node', 'java', 'golang', 'c++', 'c#',
  'data', 'ai', 'machine learning', 'cloud', 'devops', 'qa', 'tech',
  'ሶፍትዌር', 'ዴቨሎፐር', 'ኮምፒውተር', 'አይቲ', 'ዌብሳይት', 'ኢንፎርሜሽን ቴክኖሎጂ'
];

// STRICT EXCLUSIONS: Exclude non-tech, seniors, and graduate-only roles
const excludeKeywords = [
  'human resources', 'recruiter', 'care navigator', 'nurse', 'medical', 
  'sales representative', 'customer service', 'receptionist', 'driver', 'ፎርማን', 'ሹፌር', 'ሂሳብ ሹም',
  'senior', 'lead', 'principal', 'manager', 'director', 'phd', 'graduate program', 'experienced'
];

for (const item of items) {
  const json = item.json;

  // Guard against failed HTTP requests (continueOnFail resilience)
  if (!json || json.error) {
    continue;
  }

  // 1. Jobicy Global API
  if (json.jobs && Array.isArray(json.jobs)) {
    for (const job of json.jobs) {
      normalizedJobs.push({
        title: job.jobTitle,
        company: job.companyName,
        location: job.jobGeo || 'Remote Worldwide',
        url: job.url,
        description: (job.jobDescription || job.jobExcerpt || '').replace(/<[^>]*>/g, '').slice(0, 800),
        pubDate: job.pubDate || 'Recently posted',
        salary: (job.salaryMin && job.salaryMax) ? `${job.salaryCurrency || '$'}${job.salaryMin} - ${job.salaryMax}` : 'Not Specified',
        source: 'Jobicy Global'
      });
    }
  } 
  // 2. RemoteOK API
  else if (json.position) {
    normalizedJobs.push({
      title: json.position,
      company: json.company,
      location: json.location || 'Remote',
      url: json.apply_url || json.url,
      description: (json.description || '').replace(/<[^>]*>/g, '').slice(0, 800),
      pubDate: json.date ? json.date.split('T')[0] : 'Recently posted',
      salary: (json.salary_min && json.salary_max) ? `$${json.salary_min} - $${json.salary_max}` : 'Not Specified',
      source: 'RemoteOK',
      tags: json.tags || []
    });
  }
  // 3. Ethiopian Telegram Channels (Afriwork, GetJobs, Freelance Ethio)
  else if (json.data && typeof json.data === 'string' && json.data.includes('tgme_widget_message_text')) {
    const html = json.data;

    // Identify channel source
    let channelSource = 'Telegram (Ethiopia)';
    let channelDefaultUrl = 'https://t.me/afriworkamharic';
    if (html.includes('getjobss')) {
      channelSource = 'GetJobs (ET Telegram)';
      channelDefaultUrl = 'https://t.me/getjobss';
    } else if (html.includes('freelance_ethio')) {
      channelSource = 'Freelance Ethio (ET Telegram)';
      channelDefaultUrl = 'https://t.me/freelance_ethio';
    } else if (html.includes('afriworkamharic')) {
      channelSource = 'Afriwork (ET Telegram)';
      channelDefaultUrl = 'https://t.me/afriworkamharic';
    }

    const postBlockRegex = /<div class="tgme_widget_message\s[^"]*"[^>]*data-post="([^"]+)"[\s\S]*?<div class="tgme_widget_message_text[^>]*>([\s\S]*?)<\/div>/g;
    let match;
    let foundPosts = 0;
    while ((match = postBlockRegex.exec(html)) !== null) {
      foundPosts++;
      const postSlug = match[1];
      const rawText = match[2].replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
      const directUrl = postSlug ? `https://t.me/${postSlug}` : channelDefaultUrl;

      if (rawText.length > 40) {
        normalizedJobs.push({
          title: rawText.slice(0, 70),
          company: 'Ethiopian Tech Employer',
          location: 'Ethiopia (Addis Ababa / Hybrid)',
          url: directUrl,
          description: rawText.slice(0, 800),
          pubDate: 'Recently posted',
          salary: 'See description (ETB)',
          source: channelSource
        });
      }
    }
    if (foundPosts === 0) {
      const fallbackRegex = /<div class="tgme_widget_message_text[^>]*>([\s\S]*?)<\/div>/g;
      let fbMatch;
      while ((fbMatch = fallbackRegex.exec(html)) !== null) {
        const raw = fbMatch[1].replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
        if (raw.length > 40) {
          normalizedJobs.push({
            title: raw.slice(0, 70),
            company: 'Ethiopian Tech Employer',
            location: 'Ethiopia (Addis Ababa / Hybrid)',
            url: channelDefaultUrl,
            description: raw.slice(0, 800),
            pubDate: 'Recently posted',
            salary: 'See description (ETB)',
            source: channelSource
          });
        }
      }
    }
  }
}

// 1. FILTER: Strict student tech internship criteria
const filtered = normalizedJobs.filter(job => {
  const title = (job.title || '').toLowerCase();
  const desc = (job.description || '').toLowerCase();
  const allText = title + ' ' + (job.tags || []).join(' ') + ' ' + desc;

  if (excludeKeywords.some(ex => title.includes(ex))) return false;
  const isTech = techKeywords.some(kw => allText.includes(kw.toLowerCase()));
  const isStudentIntern = title.includes('intern') || 
                          title.includes('student') || 
                          title.includes('trainee') || 
                          desc.includes('internship') ||
                          desc.includes('student') ||
                          desc.includes('ተማሪ') ||
                          desc.includes('ኢንተርን') ||
                          (job.tags && (job.tags.includes('internship') || job.tags.includes('intern')));

  return isTech && isStudentIntern;
});

// 2. DEDUPLICATION ENGINE: Filter duplicates in current execution AND against historic runs
const seenInCurrentRun = new Set();
const freshJobs = [];

for (const job of filtered) {
  const cleanUrl = (job.url || '').trim().toLowerCase();
  const cleanTitle = (job.title || '').trim().toLowerCase().slice(0, 40);
  const dedupeKey = cleanUrl || cleanTitle;

  if (!dedupeKey) continue;
  if (seenInCurrentRun.has(dedupeKey)) continue;
  seenInCurrentRun.add(dedupeKey);

  // Check persistent memory across scheduled runs
  if (staticData.seenJobKeys.includes(dedupeKey)) {
    continue;
  }

  freshJobs.push(job);
}

// Take up to 3 fresh new jobs per scheduled cycle
const selectedJobs = freshJobs.slice(0, 3);

// Record newly published jobs in static memory
for (const job of selectedJobs) {
  const key = ((job.url || '').trim().toLowerCase()) || ((job.title || '').trim().toLowerCase().slice(0, 40));
  staticData.seenJobKeys.push(key);
}

// Limit memory size to 500 keys to keep workflow lightweight
if (staticData.seenJobKeys.length > 500) {
  staticData.seenJobKeys = staticData.seenJobKeys.slice(-400);
}

return selectedJobs.map(j => ({ json: j }));

